\begin{proposition}
\label{prop:parallel-field-characterization}
\dcref{ch4:4.36}
Let $M$ be a smooth manifold, possibly with boundary, with a connection $\nabla$
in $TM$. A smooth vector or tensor field $A$ is parallel on $M$ if and only if
$\nabla A\equiv0$.
\end{proposition}

